solution:
public class Maximo {
    static int maximo(int... numeros) {
        if (numeros.length == 0) return Integer.MIN_VALUE;
        int max = numeros[0];
        for (int n : numeros) {
            if (n > max) max = n;
        }
        return max;
    }

    public static void main(String[] args) {
        System.out.println("Max: " + maximo(5, 3, 9, 1, 7));
        System.out.println("Max: " + maximo(42));
        System.out.println("Max: " + maximo());
    }
}

