solution:
public class BusquedaBinaria {
    static int busquedaBinaria(int[] arr, int obj, int bajo, int alto) {
        if (bajo > alto) return -1;
        int medio = (bajo + alto) / 2;
        if (arr[medio] == obj) return medio;
        if (arr[medio] < obj) return busquedaBinaria(arr, obj, medio + 1, alto);
        return busquedaBinaria(arr, obj, bajo, medio - 1);
    }

    public static void main(String[] args) {
        int[] datos = {2, 5, 8, 12, 16, 23, 38, 45, 67, 91};
        System.out.println("23 at: " + busquedaBinaria(datos, 23, 0, datos.length - 1));
        System.out.println("50 at: " + busquedaBinaria(datos, 50, 0, datos.length - 1));
    }
}
